package com.jashyard.prayericons;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Configuration for the Prayer Icons Overlay plugin.
 *
 * This plugin is purely visual: it reads prayer on/off state from the game
 * client and draws icons. Nothing here triggers a click, key press, or any
 * other input. Every option below only affects how the overlay LOOKS.
 */
@ConfigGroup("prayericons")
public interface PrayerIconsConfig extends Config
{
	/**
	 * How active prayer icons are arranged inside the overlay.
	 */
	enum Layout
	{
		HORIZONTAL,
		VERTICAL,
		GRID
	}

	/**
	 * How large the prayer icons are drawn.
	 *
	 * REGULAR draws each sprite at its real, native pixel size (what the
	 * overlay has always done). SMALL draws it at half that size, for
	 * players who want the overlay to take up less screen space. LARGE
	 * draws it at one and a half times native size.
	 *
	 * Width and height are always scaled by the same factor, so an icon
	 * can never end up stretched or squished at any of these settings.
	 */
	enum IconSize
	{
		SMALL("Small (half size)", 0.5),
		REGULAR("Regular", 1.0),
		LARGE("Large (1.5x)", 1.5);

		private final String label;
		private final double scale;

		IconSize(String label, double scale)
		{
			this.label = label;
			this.scale = scale;
		}

		public double getScale()
		{
			return scale;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	// ------------------------------------------------------------------
	// Appearance
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "overlayPosition",
		name = "Anchor position",
		description = "Where the overlay snaps to initially. You can still drag it anywhere "
			+ "using RuneLite's normal overlay edit mode; this just sets the starting corner.",
		position = 1
	)
	default OverlayPosition overlayPosition()
	{
		return OverlayPosition.TOP_LEFT;
	}

	@ConfigItem(
		keyName = "layout",
		name = "Layout",
		description = "Arrange active prayer icons in a row, column, or wrapping grid.",
		position = 2
	)
	default Layout layout()
	{
		return Layout.HORIZONTAL;
	}

	@Range(min = 1, max = 12)
	@ConfigItem(
		keyName = "gridColumns",
		name = "Grid columns",
		description = "Number of icons per row when Layout is set to GRID.",
		position = 3
	)
	default int gridColumns()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "iconSize",
		name = "Icon size",
		description = "Regular draws each prayer icon at its real, native size. "
			+ "Small draws it at half size and Large at one and a half times size. "
			+ "Width and height always scale together, so icons never look stretched.",
		position = 4
	)
	default IconSize iconSize()
	{
		return IconSize.REGULAR;
	}

	// ------------------------------------------------------------------
	// Which prayers to show
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "showOverheadPrayers",
		name = "Include overhead prayers",
		description = "On by default. Includes the six prayers that already display an icon above your head "
			+ "(Protect from Magic/Missiles/Melee, Retribution, Redemption, Smite). "
			+ "Turn this off to hide them from this overlay only. They still appear above "
			+ "your character in game exactly as normal; nothing about the game changes.",
		position = 5
	)
	default boolean showOverheadPrayers()
	{
		return true;
	}

	// ------------------------------------------------------------------
	// Background panel
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "showBackground",
		name = "Show background",
		description = "Draws a panel behind the icons so they stand out against any part of "
			+ "the game screen. Turn off to show just the icons with nothing behind them.",
		position = 6
	)
	default boolean showBackground()
	{
		return true;
	}

	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background colour",
		description = "Colour of the panel drawn behind the icons. How see-through it is "
			+ "is controlled by \"Background opacity\" below, not by this picker.",
		position = 7
	)
	default Color backgroundColor()
	{
		return new Color(15, 15, 15);
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "backgroundOpacity",
		name = "Background opacity",
		description = "Opacity of the panel drawn behind the icons, 0 = fully transparent, "
			+ "100 = solid. Only applies when \"Show background\" is on. Icons themselves are "
			+ "always drawn fully visible so the information stays readable.",
		position = 8
	)
	default int backgroundOpacity()
	{
		return 60;
	}

	// ------------------------------------------------------------------
	// Refresh timing
	// ------------------------------------------------------------------

	@ConfigItem(
		keyName = "syncToGameTicks",
		name = "Update on game ticks",
		description = "Off (default): the overlay refreshes every frame, in real time. "
			+ "On: the overlay only refreshes once per game tick (every 0.6s), so icons "
			+ "appear and disappear on tick boundaries instead of instantly. This only "
			+ "changes when the display redraws; it does not add any timers, counters, "
			+ "or predictions, and it never changes your prayers.",
		position = 9
	)
	default boolean syncToGameTicks()
	{
		return false;
	}
}

package com.jashyard.prayericons;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Prayer;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws icons for currently active prayers.
 *
 * READ-ONLY / VISUAL-ONLY: this class only ever READS prayer state via
 * {@link Client#isPrayerActive(Prayer)} (plus a couple of read-only varbit
 * checks, see below) and draws images. It never calls any method that
 * presses a key, clicks a widget, or otherwise interacts with the game. If
 * no prayers are active it renders nothing, same as a normal buff/timer
 * overlay.
 */
public class PrayerIconsOverlay extends Overlay
{
	// Fixed padding around/between icons, in pixels.
	private static final int PADDING = 4;

	/**
	 * The six standard-spellbook prayers that draw an icon above the
	 * player's head in game. Per the OSRS Wiki's "Overheads" article, these
	 * are exactly: Protect from Magic, Protect from Missiles, Protect from
	 * Melee, Retribution, Redemption and Smite. Protect Item is explicitly
	 * NOT an overhead prayer (the Prayer table lists "No" in its overhead
	 * column), so it is not included here.
	 *
	 * This set is only ever used to decide whether to DRAW an icon in this
	 * overlay. Turning overheads off here changes nothing in game: the head
	 * icon above the player still renders exactly as normal.
	 */
	private static final Set<Prayer> OVERHEAD_PRAYERS = Collections.unmodifiableSet(EnumSet.of(
		Prayer.PROTECT_FROM_MAGIC,
		Prayer.PROTECT_FROM_MISSILES,
		Prayer.PROTECT_FROM_MELEE,
		Prayer.RETRIBUTION,
		Prayer.REDEMPTION,
		Prayer.SMITE
	));

	private final Client client;
	private final PrayerIconsConfig config;
	private final SpriteManager spriteManager;

	// Cache of loaded prayer sprites so we don't hit SpriteManager every frame.
	private final Map<Prayer, BufferedImage> spriteCache = new EnumMap<>(Prayer.class);

	// Cache of pre-scaled sprites, so the "Icon size" option never costs us a
	// resize on the render path (which runs every frame).
	private final Map<Prayer, BufferedImage> scaledCache = new EnumMap<>(Prayer.class);
	private PrayerIconsConfig.IconSize cachedIconSize = null;

	/**
	 * Snapshot of the active prayers as of the last game tick, used only
	 * when the "Update on game ticks" option is enabled. Written from the
	 * client thread in {@link #onGameTick()} and read from the render path,
	 * hence volatile.
	 */
	private volatile List<Prayer> tickSnapshot = Collections.emptyList();

	/**
	 * The size this overlay reports to RuneLite. It only ever grows, and it
	 * is deliberately NOT the size of what is currently drawn.
	 *
	 * RuneLite positions a right- or bottom-aligned overlay by subtracting
	 * the overlay's width/height from the anchor, using the bounds left over
	 * from the PREVIOUS frame (SnapCorner.getNextDrawPosition: "out.x -=
	 * bounds.width"). So any time our reported size changes, the overlay is
	 * drawn one frame at the old offset before correcting, which reads as a
	 * slide or a twitch. Reporting a size that never shrinks means the
	 * anchor stops moving, so icons switch on and off in a fixed spot.
	 *
	 * Reset whenever a setting changes the geometry (layout, grid columns,
	 * icon size), since those legitimately change what the overlay needs.
	 */
	private Dimension reservedSize = null;

	// Geometry-affecting settings, tracked so a change to any of them resets
	// the reservation above and the scaled-icon cache below.
	private PrayerIconsConfig.Layout cachedLayout = null;
	private int cachedGridColumns = -1;

	@Inject
	private PrayerIconsOverlay(Client client, PrayerIconsConfig config, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.spriteManager = spriteManager;

		// ABOVE_SCENE + a non-dynamic position makes this a normal, draggable
		// RuneLite overlay: users can move it via the standard overlay edit
		// mode (right-click the sidebar wrench icon > "Edit mode", drag with
		// the mouse, then exit edit mode). Nothing custom to build for that.
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.TOP_LEFT);
	}

	// Note: Overlay#setPosition(OverlayPosition) is already public on the base
	// class. The plugin calls it directly (once on startup, and again only
	// when the "Anchor position" config dropdown changes) so it never fights
	// with the user manually dragging the overlay in edit mode.

	/**
	 * Recomputes the active-prayer snapshot. Called by the plugin from its
	 * GameTick subscription (and once at startup / when the tick option is
	 * toggled) so that, with "Update on game ticks" enabled, the drawn set
	 * only changes on tick boundaries rather than every rendered frame.
	 *
	 * This is still a pure read of existing game state. It adds no timing
	 * information, no counters and no predictions; it only decides how often
	 * the same "what is on right now" question gets re-asked.
	 */
	void onGameTick()
	{
		tickSnapshot = getActiveVisiblePrayers();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		syncGeometrySettings();

		// Either use the once-per-tick snapshot, or read live game state on
		// this frame. Both paths are read-only.
		List<Prayer> active = config.syncToGameTicks()
			? tickSnapshot
			: getActiveVisiblePrayers();

		if (active.isEmpty())
		{
			// Nothing to paint, but still report a size so the bounds never
			// collapse to zero and drag the anchor around. Seed the
			// reservation with a single cell the very first time, so even
			// the first prayer of the session switches on without a slide.
			return reserve(singleCellSize());
		}

		int count = active.size();

		// Resolve sprites up front, already scaled to the configured icon
		// size. Only prayers whose sprite has actually finished loading are
		// included, same skip-if-not-ready behavior as before.
		List<BufferedImage> images = new ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			BufferedImage image = getIcon(active.get(i));
			if (image != null)
			{
				images.add(image);
			}
		}

		if (images.isEmpty())
		{
			return reserve(singleCellSize());
		}

		count = images.size();

		int columns;
		int rows;
		switch (config.layout())
		{
			case VERTICAL:
				columns = 1;
				rows = count;
				break;
			case GRID:
				columns = Math.max(1, config.gridColumns());
				rows = (int) Math.ceil(count / (double) columns);
				break;
			case HORIZONTAL:
			default:
				columns = count;
				rows = 1;
				break;
		}

		// Icons aren't all the same native size, so grid cells are sized to
		// the largest icon actually being shown right now. This keeps rows
		// and columns aligned without ever distorting an individual icon.
		int cellWidth = 1;
		int cellHeight = 1;
		for (BufferedImage image : images)
		{
			cellWidth = Math.max(cellWidth, image.getWidth());
			cellHeight = Math.max(cellHeight, image.getHeight());
		}

		int width = PADDING + columns * (cellWidth + PADDING);
		int height = PADDING + rows * (cellHeight + PADDING);

		// Background panel. This is fully independent of the icons: the
		// "Show background" toggle turns the whole panel on/off, "Background
		// colour" picks the colour, and "Background opacity" controls how
		// solid it looks. Alpha comes from the opacity slider alone so there
		// is only ever one thing controlling see-through-ness. Icons are
		// always drawn fully opaque regardless of any of it, so the
		// information stays readable at a glance.
		if (config.showBackground())
		{
			int bgAlpha = (int) Math.round(config.backgroundOpacity() / 100.0 * 255.0);
			if (bgAlpha > 0)
			{
				Color base = config.backgroundColor();
				if (base == null)
				{
					base = new Color(15, 15, 15);
				}

				graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), bgAlpha));
				graphics.fillRoundRect(0, 0, width, height, 6, 6);
			}
		}

		for (int i = 0; i < count; i++)
		{
			BufferedImage image = images.get(i);

			int col = i % columns;
			int row = i / columns;

			int cellX = PADDING + col * (cellWidth + PADDING);
			int cellY = PADDING + row * (cellHeight + PADDING);

			// Centre each icon within its cell so mixed icon sizes still
			// line up cleanly.
			int x = cellX + (cellWidth - image.getWidth()) / 2;
			int y = cellY + (cellHeight - image.getHeight()) / 2;

			graphics.drawImage(image, x, y, null);
		}

		// The panel and icons above are drawn from this overlay's origin at
		// their true current size, so they grow and shrink in place. Only
		// the RESERVED size is reported to RuneLite, so the overlay's anchor
		// never moves as prayers come and go.
		return reserve(new Dimension(width, height));
	}

	/**
	 * Grows the reservation to cover the given size and returns the
	 * reservation. Never shrinks, so the overlay's anchor stops moving once
	 * it has seen the widest arrangement you actually use.
	 */
	private Dimension reserve(Dimension size)
	{
		if (size == null)
		{
			return copyOf(reservedSize);
		}

		if (reservedSize == null)
		{
			reservedSize = new Dimension(size);
		}
		else
		{
			reservedSize.setSize(
				Math.max(reservedSize.width, size.width),
				Math.max(reservedSize.height, size.height));
		}

		return copyOf(reservedSize);
	}

	/**
	 * The size this overlay would be with exactly one icon in it, or null if
	 * no sprite has loaded yet. Used to seed the reservation while nothing
	 * is active, so the first prayer switched on does not resize the
	 * overlay and therefore does not move it.
	 */
	private Dimension singleCellSize()
	{
		BufferedImage sample = getIcon(Prayer.PROTECT_FROM_MELEE);
		if (sample == null)
		{
			return null;
		}

		return new Dimension(
			PADDING + sample.getWidth() + PADDING,
			PADDING + sample.getHeight() + PADDING);
	}

	/**
	 * Drops the size reservation and the scaled-icon cache when a setting
	 * that changes the overlay's geometry is altered, so the overlay resizes
	 * to fit the new arrangement instead of staying stuck at the old one.
	 */
	private void syncGeometrySettings()
	{
		PrayerIconsConfig.Layout layout = config.layout();
		int gridColumns = config.gridColumns();

		if (layout != cachedLayout || gridColumns != cachedGridColumns)
		{
			cachedLayout = layout;
			cachedGridColumns = gridColumns;
			reservedSize = null;
		}
	}

	/**
	 * Defensive copy so the renderer can never mutate our remembered size.
	 * Returns null for null, which is what render() wants before anything
	 * has been drawn.
	 */
	private static Dimension copyOf(Dimension d)
	{
		return d == null ? null : new Dimension(d.width, d.height);
	}

	/**
	 * Reads which prayers are currently active from game state and filters
	 * to the ones the user has chosen to display. Pure read: no writes to
	 * game state occur here.
	 */
	private List<Prayer> getActiveVisiblePrayers()
	{
		boolean showOverheads = config.showOverheadPrayers();

		List<Prayer> active = new ArrayList<>();
		for (Prayer prayer : Prayer.values())
		{
			// Ruinous Powers prayers (Deadman/PvP-arena specific) are out of
			// scope for this overlay.
			if (prayer.name().startsWith("RP_"))
			{
				continue;
			}

			if (!showOverheads && OVERHEAD_PRAYERS.contains(prayer))
			{
				continue;
			}

			if (isPrayerReallyActive(prayer))
			{
				active.add(prayer);
			}
		}
		return active;
	}

	/**
	 * Client#isPrayerActive(Prayer) is deprecated because it does not
	 * properly disambiguate Eagle Eye/Deadeye or Mystic Might/Mystic Vigour:
	 * those pairs share the same underlying varbit, so the raw call reports
	 * BOTH as active at once even though a player only ever has one of each
	 * pair unlocked. RuneLite's own bundled "Prayer" plugin (PrayerType.java)
	 * resolves this the same way we do here: check isPrayerActive for the
	 * shared varbit, then use the unlock varbits to pick which one is
	 * actually correct. Still 100% read-only game-state checks.
	 */
	@SuppressWarnings("deprecation")
	private boolean isPrayerReallyActive(Prayer prayer)
	{
		switch (prayer)
		{
			case EAGLE_EYE:
				return client.isPrayerActive(prayer) && !isDeadeyeUnlocked();
			case DEADEYE:
				return client.isPrayerActive(prayer) && isDeadeyeUnlocked();
			case MYSTIC_MIGHT:
				return client.isPrayerActive(prayer) && !isMysticVigourUnlocked();
			case MYSTIC_VIGOUR:
				return client.isPrayerActive(prayer) && isMysticVigourUnlocked();
			default:
				return client.isPrayerActive(prayer);
		}
	}

	private boolean isDeadeyeUnlocked()
	{
		boolean inLms = client.getVarbitValue(VarbitID.BR_INGAME) != 0;
		boolean deadeye = client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED) != 0;
		return deadeye && !inLms;
	}

	private boolean isMysticVigourUnlocked()
	{
		boolean inLms = client.getVarbitValue(VarbitID.BR_INGAME) != 0;
		boolean vigour = client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) != 0;
		return vigour && !inLms;
	}

	/**
	 * Uses the gameval SpriteID.Prayeron constants (the current, non-magic-
	 * number source of truth for prayer icon sprites) rather than hardcoded
	 * integers.
	 */
	private int spriteIdFor(Prayer prayer)
	{
		switch (prayer)
		{
			case THICK_SKIN: return SpriteID.Prayeron.THICK_SKIN;
			case BURST_OF_STRENGTH: return SpriteID.Prayeron.BURST_OF_STRENGTH;
			case CLARITY_OF_THOUGHT: return SpriteID.Prayeron.CLARITY_OF_THOUGHT;
			case SHARP_EYE: return SpriteID.Prayeron.SHARP_EYE;
			case MYSTIC_WILL: return SpriteID.Prayeron.MYSTIC_WILL;
			case ROCK_SKIN: return SpriteID.Prayeron.ROCK_SKIN;
			case SUPERHUMAN_STRENGTH: return SpriteID.Prayeron.SUPERHUMAN_STRENGTH;
			case IMPROVED_REFLEXES: return SpriteID.Prayeron.IMPROVED_REFLEXES;
			case RAPID_RESTORE: return SpriteID.Prayeron.RAPID_RESTORE;
			case RAPID_HEAL: return SpriteID.Prayeron.RAPID_HEAL;
			case PROTECT_ITEM: return SpriteID.Prayeron.PROTECT_ITEM;
			case HAWK_EYE: return SpriteID.Prayeron.HAWK_EYE;
			case MYSTIC_LORE: return SpriteID.Prayeron.MYSTIC_LORE;
			case STEEL_SKIN: return SpriteID.Prayeron.STEEL_SKIN;
			case ULTIMATE_STRENGTH: return SpriteID.Prayeron.ULTIMATE_STRENGTH;
			case INCREDIBLE_REFLEXES: return SpriteID.Prayeron.INCREDIBLE_REFLEXES;
			case PROTECT_FROM_MAGIC: return SpriteID.Prayeron.PROTECT_FROM_MAGIC;
			case PROTECT_FROM_MISSILES: return SpriteID.Prayeron.PROTECT_FROM_MISSILES;
			case PROTECT_FROM_MELEE: return SpriteID.Prayeron.PROTECT_FROM_MELEE;
			case EAGLE_EYE: return SpriteID.Prayeron.EAGLE_EYE;
			case MYSTIC_MIGHT: return SpriteID.Prayeron.MYSTIC_MIGHT;
			case RETRIBUTION: return SpriteID.Prayeron.RETRIBUTION;
			case REDEMPTION: return SpriteID.Prayeron.REDEMPTION;
			case SMITE: return SpriteID.Prayeron.SMITE;
			case PRESERVE: return SpriteID.Prayeron.PRESERVE;
			case CHIVALRY: return SpriteID.Prayeron.CHIVALRY;
			case PIETY: return SpriteID.Prayeron.PIETY;
			case RIGOUR: return SpriteID.Prayeron.RIGOUR;
			case AUGURY: return SpriteID.Prayeron.AUGURY;
			case DEADEYE: return SpriteID.Prayeron.DEADEYE;
			case MYSTIC_VIGOUR: return SpriteID.Prayeron.MYSTIC_VIGOUR;
			default: return -1;
		}
	}

	/**
	 * Returns the icon to draw for a prayer at the configured size.
	 *
	 * At REGULAR size this is the native sprite, unchanged. At SMALL and
	 * LARGE it is a rescaled copy, generated once and cached, so the
	 * per-frame render path never performs an image resize. Width and height
	 * use the same scale factor, so nothing is ever stretched. Changing the
	 * size setting clears the scaled cache so the new size is picked up.
	 */
	private BufferedImage getIcon(Prayer prayer)
	{
		PrayerIconsConfig.IconSize size = config.iconSize();
		if (size != cachedIconSize)
		{
			scaledCache.clear();
			cachedIconSize = size;
			reservedSize = null;
		}

		BufferedImage source = getSprite(prayer);
		if (source == null || size == null || size == PrayerIconsConfig.IconSize.REGULAR)
		{
			return source;
		}

		BufferedImage cached = scaledCache.get(prayer);
		if (cached != null)
		{
			return cached;
		}

		int width = Math.max(1, (int) Math.round(source.getWidth() * size.getScale()));
		int height = Math.max(1, (int) Math.round(source.getHeight() * size.getScale()));

		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = scaled.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.drawImage(source, 0, 0, width, height, null);
		}
		finally
		{
			g.dispose();
		}

		scaledCache.put(prayer, scaled);
		return scaled;
	}

	/**
	 * Lazily loads and caches the sprite for a prayer. Returns null on the
	 * first few calls until SpriteManager finishes loading it, at which
	 * point it's cached permanently (icons don't change at runtime).
	 */
	private BufferedImage getSprite(Prayer prayer)
	{
		BufferedImage cached = spriteCache.get(prayer);
		if (cached != null)
		{
			return cached;
		}

		int spriteId = spriteIdFor(prayer);
		if (spriteId < 0)
		{
			return null;
		}

		BufferedImage image = spriteManager.getSprite(spriteId, 0);
		if (image != null)
		{
			spriteCache.put(prayer, image);
		}
		return image;
	}
}

package com.jashyard.prayericons;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Prayer Icons Overlay
 *
 * Purely visual/informational plugin. It shows an icon for every currently
 * active prayer (Piety, Rigour, Augury, Protect from Melee, etc.) in a small
 * configurable overlay, similar in spirit to RuneLite's built-in
 * "Status/Timers & Buffs" style overlays.
 *
 * SAFETY: this plugin contains NO input handling. It never calls any mouse,
 * keyboard, or widget-interaction API. It only reads prayer state via
 * Client#isPrayerActive(Prayer) and draws sprites. There is nothing here
 * that could be considered automation, scripting, or botting.
 */
@PluginDescriptor(
	name = "Prayer Icons Overlay",
	description = "Shows icons for your currently active prayers in a configurable overlay. "
		+ "Visual only, no automation.",
	tags = {"prayer", "overlay", "icons", "buffs", "timers"}
)
public class PrayerIconsPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PrayerIconsOverlay overlay;

	@Inject
	private PrayerIconsConfig config;

	@Inject
	private ClientThread clientThread;

	@Provides
	PrayerIconsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PrayerIconsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlay.setPosition(config.overlayPosition());
		overlayManager.add(overlay);

		// Prime the tick snapshot so enabling the plugin with "Update on
		// game ticks" already on doesn't show an empty overlay until the
		// next tick arrives.
		//
		// This MUST be queued onto the client thread. startUp() runs on the
		// Swing EDT when the user flips the plugin's toggle in the config
		// panel, and reading prayer state from there trips RuneLite's
		// "must be called on client thread" assertion, which aborts
		// startUp() and makes the toggle snap straight back off.
		clientThread.invokeLater(overlay::onGameTick);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	/**
	 * Feeds the overlay's once-per-tick snapshot of active prayers, used
	 * when the "Update on game ticks" option is enabled.
	 *
	 * This is a read of state the client already has. It adds no timers,
	 * counters, or predictions of any kind, and never changes a prayer.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		overlay.onGameTick();
	}

	/**
	 * Re-snap the overlay to the chosen corner when the user changes the
	 * "Anchor position" dropdown.
	 *
	 * Calling overlay.setPosition(...) alone only updates the overlay's
	 * default/fallback position (Overlay#position). RuneLite's renderer
	 * (OverlayRenderer#getCorrectedOverlayPosition) actually prioritizes
	 * Overlay#preferredPosition whenever it's non-null, and that field gets
	 * permanently set the first time the overlay is dragged onto a snap
	 * corner in edit mode. Once that's happened, setPosition() alone is
	 * silently ignored forever, which is exactly the bug reported: picking
	 * a new Anchor position did nothing after the overlay had been moved.
	 * Explicitly setting preferredPosition (and clearing any stored manual
	 * drag location) and saving via OverlayManager is what actually forces
	 * the overlay to re-snap, confirmed against RuneLite's own
	 * Overlay.java/OverlayManager.java/OverlayRenderer.java source.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"prayericons".equals(event.getGroup()))
		{
			return;
		}

		if ("overlayPosition".equals(event.getKey()))
		{
			OverlayPosition newPosition = config.overlayPosition();
			overlay.setPosition(newPosition);
			overlay.setPreferredPosition(newPosition);
			overlay.setPreferredLocation(null);
			overlayManager.saveOverlay(overlay);
		}
		else if ("syncToGameTicks".equals(event.getKey())
			|| "showOverheadPrayers".equals(event.getKey()))
		{
			// Refresh the snapshot so toggling either option takes effect
			// straight away rather than on the next tick. Queued onto the
			// client thread for the same reason as in startUp(): config
			// changes are delivered on the EDT, and prayer state can only
			// be read from the client thread.
			clientThread.invokeLater(overlay::onGameTick);
		}
	}
}

